<?php declare( strict_types=1 ); namespace Inc\Services\Exam; use Inc\Repositories\OptionsRepositories\NotificationRepository; class ExamNotificationService { private NotificationRepository $notificationRepo; public function __construct( ?NotificationRepository $notificationRepo = null ) { $this->notificationRepo = $notificationRepo ?? new NotificationRepository(); } public function notifyRegistration( int $participationId, int $personId ): void { $this->notificationRepo->create( [ 'person_id' => $personId, 'type' => 'exam_registered', 'title' => 'Вы записались на экзамен', 'message' => 'Проверьте дату и время проведения', 'link' => '/exams/', ] ); } public function notifyApprovalReminder( int $personId, string $examTitle, string $scheduledAt ): void { $this->notificationRepo->create( [ 'person_id' => $personId, 'type' => 'exam_reminder', 'title' => "Напоминание: экзамен {$examTitle}", 'message' => "Экзамен начнётся {$scheduledAt}", 'link' => '/exams/', ] ); } public function notifyResultReady( int $personId, string $examTitle ): void { $this->notificationRepo->create( [ 'person_id' => $personId, 'type' => 'exam_result_ready', 'title' => "Результат экзамена {$examTitle}", 'message' => 'Результаты утверждены, смотрите подробности в кабинете', 'link' => '/exams/', ] ); } }
